// seoT looks up a localized string and substitutes {year}/{planet}/{sign}.
func seoT(key, lang string, repl map[string]string) string {
	m, ok := seoStr[key]
	if !ok {
		return key
	}
	s := tr(m, lang)
	for k, v := range repl {
		s = strings.ReplaceAll(s, "{"+k+"}", v)
	}
	return s
}
